python -I - <<'EOF'
import re,ast,statistics
L=[]
for l in open('results/train.log'):
    m=re.search(r"\{'loss':.*\}", l)
    if m:
        try: L.append(ast.literal_eval(m.group(0)))
        except: pass
d=[x['loss']-0.01*x['kl'] for x in L]
print('loss - beta*kl: mean',round(statistics.mean(d),6),'median',round(statistics.median(d),6),'max abs',round(max(abs(v) for v in d),5))
for i in [0,5,20,50,100,200,300,399]:
    x=L[i]; print(i+1,'loss',round(x['loss'],5),'beta*kl',round(0.01*x['kl'],5),'diff',round(x['loss']-0.01*x['kl'],6),'gn',x['grad_norm'],'std',x['reward_std'])
EOF

